// Emits a compact, reviewable source index. Pass --write to replace the
// checked-in artifact with the exact generated bytes.
import { readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { parseYamlRecords, rathenaFarmMonsterFlags } from './lib/ro-yaml-records.mjs';
import { classifyEvidence, collectScriptEvidence, loadActiveScripts, parseInstanceMaps }
  from '../ops/ro-stack/persistent-agent/audit-world-map-inventory.mjs';

const root = resolve(import.meta.dirname, '..');
const native = process.env.RO_RATHENA_ROOT ??
  'C:/Users/Administrator/source/ghost-island-rathena';
const readNative = (path) => readFile(join(native, path), 'utf8');
const inventory = JSON.parse(await readFile(join(root,
  'docs/openkore-reference/world-map-inventory.json'), 'utf8'));
const mapNames = JSON.parse(await readFile(join(root,
  'public/ro/data/map-names.json'), 'utf8')).entries;
const mapInfo = JSON.parse(await readFile(join(root,
  'public/ro/data/map-info.json'), 'utf8'));
const redMapIds = new Set((mapInfo.worldMap?.regions ?? [])
  .filter((region) => region.labelKind === 'red')
  .flatMap((region) => region.mapIds));
const mobDb = new Map(parseYamlRecords(await readFile(join(native,
  'db/re/mob_db.yml'), 'utf8')).map((mob) => [mob.Id, mob]));
// Spawn, flag, transfer and role evidence come from the active canonical
// Renewal scripts; the inventory contributes map existence and load status.
const evidence = collectScriptEvidence((await loadActiveScripts(readNative)).files,
  new Set(inventory.records.map((row) => row.id)));
const instances = new Map();
for (const path of ['db/re/instance_db.yml', 'db/import/instance_db.yml'])
  try {
    for (const [map, detail] of parseInstanceMaps(await readNative(path), path))
      instances.set(map, detail);
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
const questGatedSpawnFiles = new Set(inventory.records
  .map((row) => evidence.get(row.id))
  .filter((e) => e.transfers.some((transfer) =>
    /^npc\/(?:re\/)?quests\//.test(transfer.source)))
  .flatMap((e) => e.spawns
    .filter((spawn) => spawn.habitat === 'NORMAL_DUNGEON')
    .map((spawn) => spawn.source.split(':')[0])));
const maps = [];
for (const row of inventory.records) {
  if (!row.mapExists || !row.configuredForLoad || !row.cacheSource) continue;
  const e = evidence.get(row.id);
  // Loaded, static monster declarations are spawn evidence regardless of the
  // script's directory. Native decides final eligibility from the live moblist.
  const normalSpawns = e.spawns.filter((spawn) => spawn.count > 0 &&
    spawn.declaration === 'monster' &&
    spawn.source.split(':')[0] !== 'npc/re/mobs/championmobs.txt');
  if (normalSpawns.length === 0) continue;
  const habitats = [...new Set(normalSpawns.map((spawn) => spawn.habitat))];
  if (habitats.filter(Boolean).length > 1)
    throw new Error(`Mixed permanent spawn habitats: ${row.id}`);
  const byMob = new Map();
  for (const spawn of normalSpawns) {
    const mob = mobDb.get(Number(spawn.mobId));
    if (!mob) continue;
    const flags = rathenaFarmMonsterFlags(mob);
    if (flags.isBoss || flags.isResource || Number(mob.Level) < 1) continue;
    const previous = byMob.get(mob.Id);
    byMob.set(mob.Id, {
      id: mob.Id, level: Number(mob.Level),
      count: Number(previous?.count ?? 0) + Number(spawn.count),
      name: mob.Name ?? mob.AegisName ?? `Monster #${mob.Id}`,
    });
  }
  maps.push({
    map: row.id,
    name: mapNames[row.id] ?? row.id,
    category: classifyEvidence(e, instances.get(row.id), row.configuredForLoad).category,
    // Habitat is a UI grouping hint. It never admits or rejects a farm map.
    habitat: habitats.find(Boolean) ?? (redMapIds.has(row.id)
      ? 'NORMAL_DUNGEON' : 'NORMAL_FIELD'),
    blockedFlags: e.flags
      .map((flag) => flag.value)
      .filter((flag) => ['nowarpto', 'restricted', 'gvg', 'battleground'].includes(flag))
      .filter((flag, index, flags) => flags.indexOf(flag) === index).sort(),
    questTransferSources: e.transfers
      .filter((transfer) => /^npc\/(?:re\/)?quests\//.test(transfer.source))
      .map((transfer) => transfer.source),
    questReferenceSources: e.references
      .filter((reference) => /^npc\/(?:re\/)?quests\//.test(reference.source))
      .map((reference) => reference.source),
    questAccessReviewSources: [...new Set(normalSpawns.map((spawn) =>
      spawn.source.split(':')[0]))].filter((source) =>
      questGatedSpawnFiles.has(source)).sort(),
    // rAthena-authored arrival cells (script warp "map",x,y). The World Map
    // catalog uses them only when no physical portal lands on the map.
    scriptArrivals: [...new Map(e.transfers.filter((t) => t.x > 0 && t.y > 0)
      .map((t) => [`${t.x},${t.y}`, { x: t.x, y: t.y, source: t.source }])).values()]
      .sort((a, b) => a.x - b.x || a.y - b.y || a.source.localeCompare(b.source)),
    monsters: [...byMob.values()].sort((a, b) => a.level - b.level || a.id - b.id),
  });
}
maps.sort((a, b) => a.map.localeCompare(b.map));
const output = `${JSON.stringify({ schemaVersion: 1,
  source: 'rAthena active spawn inventory + db/re/mob_db.yml', maps })}\n`;
if (process.argv.includes('--write'))
  await writeFile(join(root, 'ops/ro-stack/persistent-agent/world-map-teleport-source.json'), output);
else process.stdout.write(output);
